<script setup lang="ts">
import {computed,ref,watch,onMounted} from 'vue';import PageHeading from '../components/PageHeading.vue';import {useUI,useData} from '../store';import {api} from '../api';import {date} from '../domain';
const ui=useUI(),data=useData(),busy=ref(false),error=ref(''),page=ref(1);const names:Record<string,string>={single:'单次',timed:'限时',permanent:'永久'},states:Record<string,string>={active:'有效',scheduled:'未开始',expired:'已过期',revoked:'已撤销',used:'已使用'};
/** 功能：加载管理员可见配对码元数据；参数：无；返回值：异步完成，不含配对码明文。 */
async function load(){if(!ui.authorized){ui.authOpen=true;return;}if(busy.value)return;busy.value=true;error.value='';try{ui.codes=(await api.codes()).codes;ui.codesLoaded=true;}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{busy.value=false;}}
// 只从已知到期/开始时间推导状态，不在本地伪造使用次数或撤销结果。
const visibleCodes=computed(()=>ui.codes.map(code=>({...code,status:code.revoked_at!==null?'revoked':code.kind==='single'&&code.uses>0?'used':code.expires_at!==null&&data.now>=code.expires_at?'expired':data.now<code.starts_at?'scheduled':code.status==='revoked'||code.status==='used'?code.status:'active'})));
watch(()=>ui.codes.length,count=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(count/10)));});
watch(()=>ui.authorized,value=>{if(value)void load();});onMounted(()=>{if(ui.authorized)void load();});
</script><template><PageHeading title="设备邀请中心" note="配对码只允许设备接入；撤销或到期不会影响已有设备令牌。" eyebrow="DEVICE ACCESS CONTROL"><el-button :loading="busy" @click="load">{{ui.authorized?'刷新记录':'授权后查看记录'}}</el-button></PageHeading><div class="access-types"><article v-for="kind in (['single','timed','permanent'] as const)" :key="kind" class="invite-card" :class="{featured:kind==='single'}"><div class="eyebrow">{{kind.toUpperCase()}} INVITATION</div><h3>{{names[kind]}}配对码</h3><p>{{kind==='single'?'默认10分钟有效，成功接入一台设备后失效。':kind==='timed'?'指定有效时间段，期间可接入多台设备。':'不自动到期，可持续使用，直到管理员撤销。'}}</p><el-button :type="kind==='single'?'primary':undefined" @click="ui.open({kind:'code',target:{kind}})">生成{{names[kind]}}配对码</el-button></article></div><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="global-alert"/><el-empty v-if="!ui.authorized" description="配对码记录需要管理员授权；页面可见不代表拥有管理权限"/><section v-else class="table-panel" v-loading="busy"><el-table :data="visibleCodes.slice((page-1)*10,page*10)" empty-text="尚未生成配对码"><el-table-column prop="name" label="名称备注" min-width="200"/><el-table-column label="类型" width="100"><template #default="{row}">{{names[row.kind]}}</template></el-table-column><el-table-column label="有效时间（本机时区）" min-width="200"><template #default="{row}">{{date(row.starts_at)}}<small class="cell-sub">至 {{row.expires_at===null?'永久有效':date(row.expires_at)}}</small></template></el-table-column><el-table-column prop="uses" label="已接入台数" width="120"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'info'">{{states[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="danger" :disabled="row.revoked_at!==null" @click="ui.open({kind:'revoke',target:{...row}})">撤销</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="ui.codes.length" :page-size="10" layout="total,prev,pager,next" class="pager"/></section></template>
